from contextlib import contextmanager
from inspect import currentframe
from logging import Logger
from os import path

from ta_logcollector.logger import get_net_logger
from ta_logcollector.settings import SERVER_HOST

logger = Logger("LC")


def start():
    """Configure and setup AirPhone to collect logs"""
    logger.info("Inside {} before start".format(path.basename(__file__)))
    logger.info("Inside {} after start".format(path.basename(__file__)))


def stop(log_dir):
    # type: (str) -> None
    """
    Method stop collecting and store AirPhone logs.

    :param log_dir: string containing the destination where to save logs.
    """
    logger.info("Inside {} before stop".format(path.basename(__file__)))
    logger.info("Inside {} after stop".format(path.basename(__file__)))


@contextmanager
def airphone(log_host, log_port, **kwargs):
    # type: (str, int, dict) -> None
    """
    Plugin for collecting AirPhone logs.

    :param log_host: IP address of logger host
    :param log_port: port of logger host
    """
    global logger
    logger = get_net_logger(log_host, log_port, "{}_{}".format(currentframe().f_code.co_name, SERVER_HOST))
    log_dir = kwargs.pop("log_dir")
    try:
        start()
        yield
    finally:
        stop(log_dir)
